// Patient Care Technician Practice Test 5. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items and covering topics not used in Practice Tests 1–4.
import {q, mix} from './q.js';
const NHA='NHA PCT Skills Builder Plus', NHAG='NHA CPCT/A Online Study Guide';
const CARE='Patient Care', COMP='Compliance, Safety, & Professional Responsibility', INF='Infection Control', PHL='Phlebotomy', EKG='EKG';

export default {
 id:'patient-care-technician-5',
 event:'Patient Care Technician',
 title:'Practice Test 5',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'NHA PCT Skills Builder Plus and the NHA CPCT/A Online Study Guide',
 plan:[{area:CARE,weight:44},{area:COMP,weight:20},{area:INF,weight:12},{area:PHL,weight:14},{area:EKG,weight:10}],
 questions:mix([
  q(CARE,'Thick yellow-green drainage comes from a surgical wound. What type of drainage is this?','Purulent',['Serous, which is clear and thin like water','Sanguineous, which is bright red blood','Serosanguineous, which is pink and watery'],'A','Purulent drainage contains pus and may signal infection, so it should be reported to the nurse promptly.',NHA),
  q(CARE,'Which pain scale is used for infants and young children who cannot describe their pain?','The FLACC scale, which scores face, legs, activity, cry and consolability',['A 0 to 10 number rating scale','The Braden Scale for pressure injury risk','The Glasgow Coma Scale for level of consciousness'],'B','FLACC uses observed behaviors to rate pain in patients too young or unable to report it.',NHAG),
  q(CARE,'What is the usual maximum oxygen flow for a nasal cannula?','About 6 L/min',['About 15 L/min, the same as a nonrebreather mask','About 25 L/min','About 1 L/min only'],'C','Higher flows through a cannula dry the nose without adding much oxygen; masks are used for higher needs.',NHA),
  q(CARE,'When suctioning a tracheostomy, how long should each pass of suction last?','No more than about 10 seconds',['At least 1 full minute, to clear all secretions in one pass','About 30 seconds','As long as secretions keep coming out'],'D','Longer suctioning removes oxygen from the lungs and can cause hypoxia and a slow heart rate.',NHA),
  q(CARE,'What does a bladder scanner measure?','The amount of urine left in the bladder',['The amount of protein and glucose in the urine','The pressure inside the kidneys','The patient’s blood sugar level'],'A','A bladder scan after voiding (post-void residual) shows whether the bladder empties fully.',NHA),
  q(CARE,'Which signs suggest high blood sugar (hyperglycemia)?','Thirst, frequent urination and fruity breath',['Sweating, shakiness and sudden confusion within minutes','Slow pulse and cold, pale hands','Bright red stoma and loose stool'],'B','Hyperglycemia develops slowly; hypoglycemia comes on fast with sweating and shakiness.',NHAG),
  q(CARE,'Why is control solution run on a blood glucose meter?','To confirm that the meter and test strips are working correctly',['To clean the meter before each use','To lower a patient’s glucose before testing','To warm the patient’s finger'],'C','Quality control is done per facility policy, such as daily or when a new strip vial is opened.',NHA),
  q(CARE,'A pressure injury shows a shallow open sore or an intact blister, without deeper tissue showing. Which stage is it?','Stage 2',['Stage 1, which is intact skin that stays red when pressed','Stage 3','Stage 4'],'D','Stage 2 is partial-thickness skin loss; stage 3 reaches the fat layer.',NHA),
  q(CARE,'Moving an arm away from the midline of the body is called what?','Abduction',['Adduction, moving toward the midline','Flexion','Rotation'],'A','Abduction moves a limb away from the body; adduction brings it back toward the body.',NHA),
  q(CARE,'What is the correct order when walking with a standard walker?','Move the walker forward, step with the weaker leg, then the stronger leg',['Step with both legs first, then lift the walker forward quickly','Step with the stronger leg, then move the walker','Push the walker far ahead and walk fast to catch up'],'B','The walker provides support for the weaker leg as it moves forward.',NHA),
  q(CARE,'How should crutches be fitted for a patient?','With 2 to 3 finger widths between the top of the crutch and the armpit',['With the crutch pads pressed firmly up into the armpit','So the elbows are completely straight on the handgrips','So the tips are at least 2 feet to the side of the feet'],'C','Pressure on the armpit can damage nerves; weight should rest on the hands.',NHA),
  q(CARE,'A patient on blood thinners needs a shave. Which razor should be used?','An electric razor',['A straight razor, for the closest shave','A disposable safety blade','No shaving is ever allowed'],'D','Electric razors reduce the risk of cuts and bleeding in patients taking anticoagulants.',NHA),
  q(CARE,'Which pulse site is usually checked during CPR on an infant?','Brachial',['Carotid, on the side of the neck','Radial','Temporal'],'A','The brachial artery is on the inside of the upper arm, between the elbow and shoulder.',NHA),
  q(CARE,'When taking a manual blood pressure, which sound marks the diastolic pressure?','The point when the sounds disappear',['The first clear tapping sound heard through the stethoscope','A loud whooshing sound','The first time the needle moves'],'B','Systolic is the first clear sound; diastolic is when the sounds stop.',NHA),
  q(CARE,'During postmortem care, what is usually done with the patient’s dentures?','Place them in the mouth if policy allows, or label and send them with the body',['Throw them away with the linens','Give them to the roommate','Leave them on the bedside table without a label'],'C','Dentures help keep the face natural in appearance; follow facility policy.',NHA),
  q(CARE,'A patient begins having a seizure in bed. What should the PCT do?','Protect the head, time the seizure and call for help',['Hold the arms and legs down firmly until it stops','Place a spoon in the mouth to protect the tongue','Give the patient water to drink'],'D','Never restrain or put anything in the mouth; turn to the side afterward if possible.',NHA),
  q(CARE,'A patient begins to fall while walking with the PCT. What should the PCT do?','Ease the patient to the floor while protecting the head',['Try to hold the patient upright with all their strength','Let go and step away to avoid injury','Pull the patient up by the arms'],'A','Guiding the fall protects both the patient and the PCT; then call for help.',NHA),
  q(CARE,'A patient who has not had a bowel movement for days now has liquid stool leaking. What may this mean?','Fecal impaction',['Normal bowel function after a laxative','A urinary tract infection','Too much fiber in the diet'],'B','Liquid stool can seep around hard, blocked stool; report it to the nurse.',NHA),
  q(CARE,'When applying a condom catheter, why is space left at the tip?','To prevent irritation and allow urine to flow freely',['To make the catheter easier to remove later','To allow the catheter to hold more air','To keep the catheter from sticking'],'C','The catheter is changed daily and the skin checked for irritation.',NHA),
  q(CARE,'In which position is the head of the bed raised and the foot lowered?','Reverse Trendelenburg',['Trendelenburg, with the head lowered','Lithotomy','Prone'],'D','Reverse Trendelenburg may be used to reduce reflux or aid breathing.',NHA),
  q(CARE,'A wound is covered by thick, dark, dead tissue so its depth cannot be seen. How is it staged?','Unstageable',['Stage 1, because the skin is not broken','Stage 2','Deep tissue injury healed'],'A','The depth cannot be judged until the dead tissue (eschar) is removed.',NHA),
  q(CARE,'Which temperature route usually gives the lowest reading?','Axillary',['Rectal, which is usually the highest reading','Oral','Tympanic'],'B','Axillary readings are about 1 °F lower than oral readings, so the route must be recorded.',NHA),
  q(COMP,'Under HIPAA, how much patient information should staff access or share?','Only the minimum necessary to do the job',['Any information the coworker is curious about','Everything in the chart, in case it is needed later','Only what the patient’s family asks for'],'C','The minimum necessary rule limits use and disclosure of protected health information.',NHAG),
  q(COMP,'A PCT has a concern about a nurse’s instructions. Who should the PCT go to first?','The nurse, then follow the chain of command if needed',['The hospital CEO directly, by email, before anyone else hears','The patient’s family','Another patient'],'D','The chain of command handles problems at the lowest level first.',NHAG),
  q(COMP,'A physician gives a PCT a verbal order for a new medication. What should the PCT do?','Explain that they cannot take orders and get the nurse',['Write down the order and give the medication','Ignore the physician','Tell the patient to take the medicine'],'A','Verbal and telephone orders are taken by licensed staff, such as nurses.',NHAG),
  q(COMP,'Which hospital emergency code often signals an infant or child abduction?','Code Pink',['Code Red, used for a fire','Code Blue','Code Gray'],'B','Codes vary by facility, so staff must learn their own facility’s codes.',NHAG),
  q(COMP,'What does PASS stand for when using a fire extinguisher?','Pull, aim, squeeze, sweep',['Push, alarm, spray, stop','Pull, alert, stand, spray','Point, aim, shoot, step'],'C','Aim at the base of the fire, not the flames, and sweep side to side until it is out.',NHAG),
  q(COMP,'A PCT starts a procedure after the patient clearly refused it. Which tort is this?','Battery',['Assault, which is only a threat of harm','Libel','Slander'],'D','Touching a patient without consent is battery, even if the procedure would have helped.',NHAG),
  q(COMP,'When a nurse delegates a task to a PCT, which is one of the five rights of delegation?','Right task',['Right patient insurance','Right shift preference','Right family request'],'A','The five rights are task, circumstance, person, direction and supervision.',NHAG),
  q(COMP,'A former patient sends the PCT a friend request on social media. What should the PCT do?','Decline, to keep professional boundaries',['Accept and chat about the hospital stay','Accept and post a photo together','Share the request with coworkers'],'B','Social media friendships with patients blur professional boundaries and risk privacy breaches.',NHAG),
  q(COMP,'A visitor is yelling and becoming agitated. What is the best first step?','Speak calmly, listen and call for help if needed',['Yell back to show authority','Physically block the visitor','Ignore the visitor and keep working'],'C','De-escalation uses a calm voice, space and listening; security is called if needed.',NHAG),
  q(COMP,'Which ethical principle means being truthful with patients?','Veracity',['Fidelity','Justice','Beneficence'],'D','Veracity builds trust with patients; fidelity, by contrast, means keeping promises.',NHAG),
  q(INF,'A patient with VRE in a wound needs care. Which precautions are used?','Contact precautions',['Airborne precautions with an N95 respirator','Droplet precautions only','No precautions are needed'],'A','Contact precautions require a gown and gloves and dedicated equipment.',NHA),
  q(INF,'In the chain of infection, a sneeze that releases germs from the body is an example of what?','A portal of exit',['A portal of entry','A reservoir','A susceptible host'],'B','Covering coughs and sneezes blocks the portal of exit so germs cannot reach a new host.',NHA),
  q(INF,'Which part of a sterile field is considered unsterile?','The outer 1-inch border',['The center of the drape, where supplies are placed','Any item that was opened less than an hour ago','Only items that are wet'],'C','The 1-inch edge of a sterile field is treated as contaminated, so sterile items are kept inside it.',NHA),
  q(INF,'Under standard precautions, which body fluid is NOT treated as potentially infectious unless it contains blood?','Sweat',['Blood, which always requires standard precautions','Wound drainage','Vomit'],'D','Standard precautions cover blood and all body fluids, secretions and excretions except sweat.',NHA),
  q(INF,'A urinary tract infection that develops because of an indwelling catheter is called what?','A catheter-associated urinary tract infection (CAUTI)',['A community-acquired infection that the patient brought from home','A congenital infection','A zoonotic infection'],'A','Removing catheters as soon as possible and keeping the system closed reduce CAUTIs.',NHA),
  q(INF,'Blood splashes onto a PCT’s broken skin. What should be done first?','Wash the area with soap and water, then report it',['Wait until the end of the shift to report it','Apply bleach to the skin','Cover it with a bandage and tell no one'],'B','Prompt reporting allows testing of the source patient and preventive treatment if needed.',NHA),
  q(PHL,'A swelling forms under the skin during a venipuncture. What should the PCT do?','Release the tourniquet, remove the needle and apply pressure',['Push the needle deeper to find the vein','Keep drawing until all tubes are full','Massage the swelling during the draw'],'C','A hematoma means blood is leaking into the tissue; stop the draw.',NHAG),
  q(PHL,'How far above the venipuncture site is the tourniquet placed?','About 3 to 4 inches',['About 1 inch','About 8 inches','At the wrist'],'D','A tourniquet too close can block the site; too far may not fill the vein well.',NHAG),
  q(PHL,'Why should a patient not pump the fist during a venipuncture?','It can falsely raise potassium levels',['It lowers the patient’s blood sugar','It makes the vein disappear completely','It causes the blood to clot in the tube'],'A','A gently closed fist is fine; repeated pumping changes some results.',NHAG),
  q(PHL,'A patient has an IV in the left forearm. Where may blood be drawn if no other site is available?','Below the IV after the nurse stops it for at least 2 minutes',['Directly from the IV tubing while the fluid keeps running','Above the IV site','From the IV insertion site'],'B','Drawing above an IV can dilute the specimen with IV fluid and give false results.',NHAG),
  q(PHL,'A patient becomes pale and says they feel faint during a draw. What should the PCT do first?','Remove the tourniquet and needle and lower the patient’s head',['Finish filling all the tubes quickly','Give the patient a cup of coffee','Ask the patient to stand up and walk'],'C','Stopping the draw and protecting the patient from falling come first.',NHAG),
  q(PHL,'For which patients is a heel puncture usually done?','Infants under about 1 year',['Teenagers with small veins','Older adults with fragile skin','Adults who fear needles'],'D','The outer sides of the heel are used to avoid puncturing the heel bone and causing infection.',NHAG),
  q(PHL,'Why must a light blue sodium citrate tube be filled completely?','To keep the correct 9:1 blood-to-anticoagulant ratio',['To keep the tube from breaking','To make the tube easier to label','Because the tube has no vacuum'],'A','An underfilled tube has too much citrate for the blood and gives falsely long clotting times.',NHAG),
  q(EKG,'On standard EKG paper, how much time does one large box represent?','0.20 seconds',['0.04 seconds, the time for one small box','1 second','0.50 seconds'],'B','One large box contains 5 small boxes of 0.04 seconds each, and 5 large boxes equal 1 second.',NHA),
  q(EKG,'Using the 6-second method, there are 7 QRS complexes in a 6-second strip. What is the heart rate?','About 70 beats per minute',['About 42 beats per minute','About 7 beats per minute','About 140 beats per minute'],'C','Multiply the QRS complexes in 6 seconds by 10; this method works well for irregular rhythms.',NHA),
  q(EKG,'A regular rhythm has normal waves but a rate of 115 beats per minute. What is it?','Sinus tachycardia',['Sinus bradycardia','Ventricular fibrillation','Atrial fibrillation'],'D','Sinus tachycardia is over 100 bpm and may be caused by fever, pain or anxiety.',NHA),
  q(EKG,'The EKG shows a flat line and the patient is unresponsive. After checking leads, what is this rhythm?','Asystole',['Normal sinus rhythm','Atrial flutter','Sinus tachycardia'],'A','Asystole is cardiac arrest; start CPR and call for help, since it is not a shockable rhythm.',NHA),
  q(EKG,'A shivering patient’s EKG has jagged, irregular lines. What is this artifact called?','Somatic tremor',['60-cycle interference','A wandering baseline','A normal P wave'],'B','Keep the patient warm and relaxed to reduce muscle tremor artifact.',NHA)
 ],9515)
};
